def max_sum(arr):
    def max_increasing_decreasing(arr):
        n = len(arr)
        if n == 0:
            return 0

        # The first step is to find the bitonic subsequence
        increasing = [0] * n
        decreasing = [0] * n

        # Initialize increasing array
        increasing[0] = arr[0]
        for i in range(1, n):
            if arr[i] > increasing[i - 1]:
                increasing[i] = arr[i]
            else:
                increasing[i] = arr[i] + increasing[i - 1]

        # Initialize decreasing array
        decreasing[n - 1] = arr[n - 1]
        for i in range(n - 2, -1, -1):
            if arr[i] > decreasing[i + 1]:
                decreasing[i] = arr[i]
            else:
                decreasing[i] = arr[i] + decreasing[i + 1]

        # Calculate the maximum sum
